// Validate envelope against contract
const body = $input.first().json || {};
const required = ['contract_version', 'source_id', 'connector_id', 'idempotency_key', 'mode', 'provider', 'required_proxy', 'preflight_required', 'direct_fallback_allowed', 'max_pages', 'deadline_seconds', 'target_url'];
const missing = required.filter(key => !(key in body));
if (missing.length > 0) {
  throw new Error('Missing required fields: ' + missing.join(', '));
}
if (body.contract_version !== 1) {
  throw new Error('Unsupported contract version: ' + body.contract_version);
}
if (body.required_proxy !== 'webshare') {
  throw new Error('Required proxy must be webshare');
}
if (body.preflight_required !== true) {
  throw new Error('Preflight must be required');
}
if (body.direct_fallback_allowed !== false) {
  throw new Error('Direct fallback must be disabled');
}
if (body.connector_id !== 'courtlistener' && body.connector_id !== 'src_courtlistener') {
  throw new Error('This workflow only handles CourtListener requests. Received: ' + body.connector_id);
}
return [{ json: { ...body, validated: true } }];

// Parse S3 XML listing and filter files
function parseS3Xml(xml) {
  const files = [];
  const keyRegex = /<Key>([^<]+)<\/Key>/g;
  const sizeRegex = /<Size>(\d+)<\/Size>/g;
  const lastModifiedRegex = /<LastModified>([^<]+)<\/LastModified>/g;

  const keys = xml.match(keyRegex) || [];
  const sizes = xml.match(sizeRegex) || [];
  const lastModifieds = xml.match(lastModifiedRegex) || [];

  for (let i = 0; i < keys.length; i++) {
    const key = keys[i].replace(/<Key>|<\/Key>/g, '');
    const size = sizes[i] ? parseInt(sizes[i].replace(/<Size>|<\/Size>/g, '')) : 0;
    const lastModified = lastModifieds[i] ? lastModifieds[i].replace(/<LastModified>|<\/LastModified>/g, '') : '';

    if (key.includes('bulk-data/') && (key.endsWith('.csv.bz2') || key.endsWith('.csv'))) {
      files.push({ Key: key, Size: size, LastModified: lastModified });
    }
  }
  return files;
}

const body = $input.first().json || {};
const xml = body.text || '';
const allFiles = parseS3Xml(xml);

// Filter by type
const fileTypes = body.file_types || [];
const filteredByType = allFiles.filter(file => 
  fileTypes.some(type => file.Key.includes(type))
);

// Filter by date range
const startDate = body.start_date;
const endDate = body.end_date;
const filteredByDate = filteredByType.filter(file => {
  const dateMatch = file.Key.match(/(\d{4}-\d{2}-\d{2})/);
  if (!dateMatch) return true;
  const fileDate = dateMatch[1];
  if (startDate && fileDate < startDate) return false;
  if (endDate && fileDate > endDate) return false;
  return true;
});

// Add metadata
const filesWithMetadata = filteredByDate.map(file => ({
  ...file,
  filename: file.Key.split('/').pop(),
  url: 'https://com-courtlistener-storage.s3-us-west-2.amazonaws.com/' + file.Key,
  source_id: body.source_id,
  run_id: body.run_id || body.idempotency_key,
  trace_id: body.trace_id,
  access_scope_id: body.access_scope_id
}));

console.log('[CourtListener] Found ' + allFiles.length + ' files, filtered to ' + filteredByDate.length);

return filesWithMetadata.map(file => ({ json: file }));

// Create Harvy event metadata
const items = $input.all();
const envelope = $input.first().json || {};
const events = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json || {};
  const binaryData = items[i].binary?.data || null;

  if (!binaryData) {
    console.warn('No binary data for ' + item.filename);
    continue;
  }

  // Create deterministic event ID
  const crypto = require('crypto');
  const hash = crypto.createHash('sha256').update(String(item.filename || item.Key || i)).digest('hex').slice(0, 16);
  const eventId = 'src_courtlistener_' + hash;

  const fileSizeGB = item.Size ? (item.Size / 1024 / 1024 / 1024).toFixed(2) : 'unknown';

  const event = {
    id: eventId,
    event_id: eventId,
    source_id: 'src_courtlistener',
    publisher: 'CourtListener',
    product: 'Civic',
    tenant_id: envelope.access_scope_id?.replace('tenant-', '') || 'shared',
    workspace_id: envelope.access_scope_id?.replace('tenant-', '') || 'shared',
    title: item.filename || 'CourtListener Bulk Data',
    summary: 'Bulk data file: ' + item.filename + ' (' + fileSizeGB + ' GB)',
    status: 'new',
    first_seen_at: new Date(item.LastModified).toISOString(),
    last_seen_at: new Date().toISOString(),
    run_id: envelope.run_id || envelope.idempotency_key,
    trace_id: envelope.trace_id,
    source_scope_id: envelope.source_scope_id || 'src_courtlistener',
    access_scope_id: envelope.access_scope_id || 'tenant-shared',
    metadata: {
      filename: item.filename,
      url: item.url,
      size: item.Size,
      last_modified: item.LastModified,
      content_type: item.filename?.endsWith('.bz2') ? 'application/x-bzip2' : 'text/csv',
      file_type: item.Key?.split('/').pop()?.replace(/\.csv\.bz2$|\.csv$/, '') || 'unknown'
    },
    provenance: {
      source: 'CourtListener Bulk Data',
      url: 'https://com-courtlistener-storage.s3-us-west-2.amazonaws.com/',
      license: 'Public Domain (RECAP)',
      retrieved_at: new Date().toISOString()
    }
  };

  events.push({ json: event, binary: { data: binaryData } });
}

return events;

// Transform to evidence format
const items = $input.all();
const evidenceList = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json || {};

  const evidence = {
    id: item.id + '-evidence',
    event_id: item.event_id,
    source_id: item.source_id,
    publisher: item.publisher,
    product: item.product,
    tenant_id: item.tenant_id,
    workspace_id: item.workspace_id,
    type: 'document',
    title: item.title,
    summary: item.summary,
    content: item.summary,
    url: item.metadata?.url,
    file_path: 'courtlistener/raw/' + item.metadata?.filename,
    file_size: item.metadata?.size,
    file_type: item.metadata?.content_type,
    first_seen_at: item.first_seen_at,
    last_seen_at: item.last_seen_at,
    run_id: item.run_id,
    trace_id: item.trace_id,
    metadata: {
      filename: item.metadata.filename,
      url: item.metadata.url,
      size: item.metadata.size,
      content_type: item.metadata.content_type,
      evidence_type: 'bulk_data_file'
    },
    provenance: item.provenance
  };

  evidenceList.push({ json: evidence });
}

return evidenceList;

